import assert from "node:assert/strict";
import { test } from "node:test";
import { summarizeChecks } from "./summarize-checks.mjs";

test("empty checks remain pending", () => {
  assert.equal(summarizeChecks([]), "pending");
});
test("all passed checks produce passed", () => {
  assert.equal(summarizeChecks([{ status: "passed" }, { status: "passed" }]), "passed");
});
test("a missing run keeps acceptance pending", () => {
  assert.equal(summarizeChecks([{ status: "passed" }, { status: "not-run" }]), "pending");
});
test("failure wins over pending in any order", () => {
  assert.equal(summarizeChecks([{ status: "failed" }, { status: "not-run" }]), "failed");
  assert.equal(summarizeChecks([{ status: "not-run" }, { status: "failed" }]), "failed");
});
test("unknown or missing status is rejected even after a failure", () => {
  assert.throws(() => summarizeChecks([{ status: "failed" }, { status: "unknown" }]), TypeError);
  assert.throws(() => summarizeChecks([{}]), TypeError);
});
test("inputs are not mutated", () => {
  const checks = Object.freeze([Object.freeze({ status: "passed", command: "node --test" })]);
  assert.equal(summarizeChecks(checks), "passed");
});

summarize-checks.mjs.content:
export function summarizeChecks(checks) {
  if (!Array.isArray(checks)) {
    throw new TypeError("Checks must be an array");
  }

  let hasFailure = false;
  let hasPending = checks.length === 0;

  for (const check of checks) {
    if (check === null || typeof check !== "object" || Array.isArray(check)) {
      throw new TypeError("Each check must be an object with a valid status");
    }

    switch (check.status) {
      case "passed":
        break;
      case "failed":
        hasFailure = true;
        break;
      case "not-run":
        hasPending = true;
        break;
      default:
        throw new TypeError("Check status must be passed, failed or not-run");
    }
  }

  return hasFailure ? "failed" : hasPending ? "pending" : "passed";
}
